-- Wilderness Trail (wildernesstraildistillery.com, re-check of the parked source) — applied 2026-10-11. part1 then inserts_1.
update cellar.products set specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://www.wildernesstraildistillery.com/app/uploads/2025/02/Group-224.webp'), name = 'Wilderness Trail High Rye Bourbon', expression = 'High Rye Bourbon', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'Wilderness Trail High Rye Bourbon Bottled in Bond')) a), producer = coalesce(producer, 'Wilderness Trail'), producer_id = coalesce(producer_id, 'ca6dd78a-e013-409c-a4a7-12461790fda3'::uuid), source = 'maker', source_url = 'https://www.wildernesstraildistillery.com/whiskeys/high-rye-bourbon/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'e0bc798a-7784-42d5-8cd7-bbb19a8ca73b' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('e0bc798a-7784-42d5-8cd7-bbb19a8ca73b');
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Wilderness Trail Wheated Bourbon","rar":"shelf","f":"Wilderness Trail","x":"Wheated Bourbon","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"wheated","mb":null,"st":"bourbon","bib":true,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Wilderness Trail Kentucky Straight Wheated Bourbon","Wilderness Trail Wheated Bourbon Bottled in Bond"],"img":"https://www.wildernesstraildistillery.com/app/uploads/2025/02/Group-225.webp","u":"https://www.wildernesstraildistillery.com/whiskeys/wheated-bourbon/","pr":"Wilderness Trail","mk":"ca6dd78a-e013-409c-a4a7-12461790fda3"},{"n":"Wilderness Trail Rye Whiskey","rar":"shelf","f":"Wilderness Trail","x":"Rye Whiskey","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"rye","mb":null,"st":"rye","bib":true,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Wilderness Trail Kentucky Straight Rye Whiskey","Wilderness Trail Rye Whiskey Bottled in Bond"],"img":"https://www.wildernesstraildistillery.com/app/uploads/2025/02/Group-226.webp","u":"https://www.wildernesstraildistillery.com/whiskeys/rye-whiskey/","pr":"Wilderness Trail","mk":"ca6dd78a-e013-409c-a4a7-12461790fda3"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');